const OUT = { month: new Date().toISOString().slice(0, 7), cp: '' };
function outMonthInvoices(month) {
return invoices.filter(row => row.date.startsWith(month) && (!scope || row.from.rfc === scope || row.to.rfc === scope));
}
function ivaRows(month) {
return people.map(person => {
let issuedIva = 0n, receivedIva = 0n, issuedCount = 0, receivedCount = 0, missing = 0;
for (const row of invoices) {
if (!row.date.startsWith(month) || row.kind !== 'I' || (row.currency && row.currency !== 'MXN')) continue;
const iva = invoiceIvaCents(row);
if (row.from.rfc === person.id) { issuedCount++; if (iva === null) missing++; else issuedIva += iva; }
if (row.to.rfc === person.id) { receivedCount++; if (iva === null) missing++; else receivedIva += iva; }
}
return { rfc: person.id, name: person.name, issuedIva, receivedIva, issuedCount, receivedCount, missing,
balance: issuedIva - receivedIva };
}).filter(row => row.issuedCount || row.receivedCount);
}













function reportesScreen201() {
const wrap = n('div');
const rfc = () => scope || people[0]?.id || '';
const hoy = new Date();
const anioDef = hoy.getFullYear();
const mesDef = anioDef + '-' + String(hoy.getMonth() + 1).padStart(2, '0');
const lista = panel('Los reportes, en un solo sitio',
'Cada reporte con su periodo y su salida: PDF para papel, Excel para trabajar e Imprimir para la vista en pantalla. Todo sale del cálculo único, como en sus pantallas.');







{
const anio = anioDef;
let emT = 0n, reT = 0n;
const porMes2913 = new Map();
for (const row of invoices) {
if (rowCancelled(row)) continue;
if (scope && row.from.rfc !== scope && row.to.rfc !== scope) continue;
if (row.currency && row.currency !== 'MXN') continue;
const mes = String(row.date || '').slice(0, 7);
if (!mes.startsWith(String(anio))) continue;
const role = roles(row);
const celda = porMes2913.get(mes) || { em: 0n, re: 0n };
if (role.issued) { emT += totalCents(row); celda.em += totalCents(row); }
if (role.received) { reT += totalCents(row); celda.re += totalCents(row); }
porMes2913.set(mes, celda);
}
const portada2913 = n('div', undefined, 'reportes-portada2913');
const cifras2913 = n('div', undefined, 'reportes-cifras2913');
const cifra2913 = (etiqueta, valor) => {
const d = n('div', undefined, 'reporte-cifra2913');
d.append(n('small', etiqueta), n('strong', valor, 'reporte-cifra-num2913'));
return d;
};
cifras2913.append(
cifra2913('Emitidos en ' + anio, '$' + centsLabel(emT)),
cifra2913('Recibidos en ' + anio, '$' + centsLabel(reT)));
portada2913.append(cifras2913);
const mesesCon2913 = [...porMes2913.keys()].sort();
if (mesesCon2913.length) {
const maxMes2913 = mesesCon2913.reduce((m, k) => {
const c = porMes2913.get(k);
return c.em > m ? c.em : c.re > m ? c.re : m;
}, 0n);
const barras2913 = n('div', undefined, 'graf-barras2913');
for (const mes of mesesCon2913) {
const c = porMes2913.get(mes);
const par2913 = n('div', undefined, 'graf-par2913');
for (const [valor, clase] of [[c.em, 'emitidos'], [c.re, 'recibidos']]) {
const b = n('div', undefined, 'graf-barra2913 ' + clase);
b.style.height = (maxMes2913 > 0n ? Math.max(3, Number(valor * 64n / maxMes2913)) : 3) + 'px';
b.title = mes + ' · ' + clase + ': $' + centsLabel(valor);
par2913.append(b);
}
const col2913 = n('div', undefined, 'graf-col2913');
col2913.append(par2913, n('span', mes.slice(5), 'graf-mes2913'));
barras2913.append(col2913);
}
portada2913.append(barras2913);
}
lista.append(portada2913);
}
const filaReporte = (titulo, detalle, periodoEl, botones, enviarOpts) => {
const fila = n('div', undefined, 'cp-row');
const main = n('div', undefined, 'cp-main');
main.append(n('strong', titulo), n('span', detalle, 'muted'));
if (periodoEl) main.append(periodoEl);
fila.append(main);
const acts = n('div', undefined, 'actions');
for (const [etiqueta, hacer, clase] of botones) {
const b = n('button', etiqueta, clase || 'soft');
b.type = 'button';
b.onclick = () => hacer(b);
acts.append(b);
}








if (enviarOpts && typeof enviarBoton240 === 'function' &&
(typeof guestMode === 'undefined' || !guestMode)) {
const b = enviarBoton240(enviarOpts, undefined, 'Enviar este reporte');
b.dataset.reporteEnviar240 = titulo;
b.title = 'Enviar · ' + titulo;
b.setAttribute('aria-label', 'Enviar · ' + titulo);
acts.append(b);
}
fila.append(acts);
lista.append(fila);
return fila;
};






const enviarReporte240 = (nombre, hacerArchivo, correoDe) => () => {
const nombreReal = typeof nombre === 'function' ? nombre() : nombre;
return {
nombre: nombreReal,
asunto: 'PacoSAT · ' + nombreReal,
correo: correoDe ? correoDe() : null,
correoNota: correoDe ? undefined :
'Este reporte se genera al momento y no está entre los que el correo de PacoSAT puede adjuntar: mándalo por WhatsApp o Compartir, o descárgalo y adjúntalo desde tu correo.',
archivo: hacerArchivo };
};
const inputAnio = valor => {
const el = input('number', { value: valor, min: 2019, max: anioDef + 1, 'aria-label': 'Ejercicio' });
el.style.maxWidth = '110px';
return el;
};

const anioTotales = inputAnio(anioDef);
filaReporte('Totales', 'Emitidos y recibidos del ejercicio, mes a mes, con sus totales.', anioTotales, [
['PDF', b => descargarSalida1310('salidas/pdf', { kind: 'totales', rfc: rfc(), year: Number(anioTotales.value) || anioDef }, b), 'primary'],
['Excel', b => descargarSalida1310('salidas/xlsx', { kind: 'totales', rfc: rfc(), year: Number(anioTotales.value) || anioDef }, b)],
['Imprimir', () => {
const anio = Number(anioTotales.value) || anioDef;
const filas = [];
for (let m = 1; m <= 12; m++) {
const clave = anio + '-' + String(m).padStart(2, '0');
let em = 0n, re = 0n, nEm = 0, nRe = 0;
for (const row of outMonthInvoices(clave)) {
if (row.currency && row.currency !== 'MXN') continue;
const role = roles(row);
if (role.issued) { em += totalCents(row); nEm++; }
if (role.received) { re += totalCents(row); nRe++; }
}
if (nEm || nRe) filas.push([DECL_MES_REP201[m - 1] + ' ' + anio, number.format(nEm), '$' + centsLabel(em), number.format(nRe), '$' + centsLabel(re)]);
}
imprimirVista201('Totales ' + anio, 'Emitidos y recibidos por mes, sin contar cancelados en los totales.',
['Mes', 'Emitidos', 'Total emitidos', 'Recibidos', 'Total recibidos'], filas);
}]
], enviarReporte240(() => 'Reporte de Totales ' + (Number(anioTotales.value) || anioDef),
() => enviarBlobSalida240('salidas/pdf', { kind: 'totales', rfc: rfc(), year: Number(anioTotales.value) || anioDef }),
() => ({ clase: 'reporte', tipo: 'totales-pdf', rfc: rfc(), year: Number(anioTotales.value) || anioDef })));


const cps = new Map();
for (const row of invoices) {
if (scope && row.from.rfc !== scope && row.to.rfc !== scope) continue;
const cp = row.from.rfc === scope ? row.to : row.from;
if (cp?.rfc && cp.rfc !== scope) cps.set(cp.rfc, cp.name || cp.rfc);
}
if (cps.size) {
const picker = select([...cps.entries()].map(([value, label]) => [value, label + ' · ' + value]), [...cps.keys()][0], 'Contraparte del reporte');
filaReporte('Por contraparte', 'Los movimientos con una contraparte: su PDF lleva folio y saldo neto en letra.', picker, [
['PDF', b => descargarSalida1310('salidas/pdf', { kind: 'contraparte', rfc: rfc(), contraparte: picker.value }, b), 'primary'],
['Imprimir', () => {
const filas = invoices.filter(row => row.from.rfc === picker.value || row.to.rfc === picker.value)
.map(row => [dateLabel(row.date), row.fiscal ? ((row.fiscal.serie ? row.fiscal.serie + '-' : '') + (row.fiscal.folio || '')) || '—' : '—',
(row.from.name || row.from.rfc) + ' → ' + (row.to.name || row.to.rfc), amount(row)]);
imprimirVista201('Reporte por contraparte · ' + (cps.get(picker.value) || picker.value),
number.format(filas.length) + ' comprobante(s).', ['Fecha', 'Folio', 'Emisor → receptor', 'Total'], filas);
}]
], enviarReporte240('Reporte por contraparte',
() => enviarBlobSalida240('salidas/pdf', { kind: 'contraparte', rfc: rfc(), contraparte: picker.value }),
() => ({ clase: 'reporte', tipo: 'contraparte-pdf', rfc: rfc(), contraparte: picker.value })));
}


const mesInput = input('month', { value: mesDef, 'aria-label': 'Mes del reporte' });
filaReporte('Por mes', 'El reporte del periodo: totales por sentido y por contraparte, con su IVA.', mesInput, [
['PDF', b => descargarSalida1310('salidas/pdf', { kind: 'periodo', rfc: rfc(), month: mesInput.value || mesDef }, b), 'primary'],
['Excel', b => descargarSalida1310('salidas/xlsx', { kind: 'facturas', rfc: rfc(), month: mesInput.value || mesDef }, b)],
['Imprimir', () => {
const clave = mesInput.value || mesDef;
const rowsMes = outMonthInvoices(clave);
let issuedTotal = 0n, receivedTotal = 0n, issuedIva = 0n, receivedIva = 0n;
for (const row of rowsMes) {
if (row.currency && row.currency !== 'MXN') continue;
const role = roles(row), iva = invoiceIvaCents(row);
if (role.issued) { issuedTotal += totalCents(row); if (iva !== null) issuedIva += iva; }
if (role.received) { receivedTotal += totalCents(row); if (iva !== null) receivedIva += iva; }
}
printPeriodReport(clave, rowsMes, { issuedTotal, receivedTotal, issuedIva, receivedIva });
}]
], enviarReporte240(() => 'Reporte del mes ' + (mesInput.value || mesDef),
() => enviarBlobSalida240('salidas/pdf', { kind: 'periodo', rfc: rfc(), month: mesInput.value || mesDef }),
() => ({ clase: 'reporte', tipo: 'periodo-pdf', rfc: rfc(), mes: mesInput.value || mesDef })));

const anioDecl = inputAnio(anioDef);
filaReporte('Declaraciones', 'El mapa del ejercicio: qué consta presentado, qué falta y qué se recuperó.', anioDecl, [
['PDF', b => descargarSalida1310('salidas/pdf', { kind: 'declaraciones', rfc: rfc(), year: Number(anioDecl.value) || anioDef }, b), 'primary'],
['Excel', b => descargarSalida1310('salidas/xlsx', { kind: 'declaraciones', rfc: rfc(), year: Number(anioDecl.value) || anioDef }, b)],
['Imprimir', async b => {
b.disabled = true;
try {
const data = await satApi('declaraciones?rfc=' + encodeURIComponent(rfc()) + '&ejercicio=' + (Number(anioDecl.value) || anioDef));
const filas = (data?.mapa?.meses || []).map(m => [DECL_MES_REP201[Number(m.periodo.slice(5, 7)) - 1],
(typeof DECL_ESTADO_TEXTO !== 'undefined' ? DECL_ESTADO_TEXTO[m.estado] : m.estado) || m.estado,
m.fechaPresentacion ? dateLabel(m.fechaPresentacion) : '—', m.operacion || '—']);
imprimirVista201('Declaraciones ' + (Number(anioDecl.value) || anioDef),
'Presentadas: ' + number.format(data?.resumen?.presentadas || 0) + ' · pendientes: ' + number.format(data?.resumen?.pendientes || 0) + '.',
['Mes', 'Estado', 'Presentada', 'Operación'], filas);
} catch (error) { toast(error.message, 'error'); }
b.disabled = false;
}]
], enviarReporte240(() => 'Reporte de Declaraciones ' + (Number(anioDecl.value) || anioDef),
() => enviarBlobSalida240('salidas/pdf', { kind: 'declaraciones', rfc: rfc(), year: Number(anioDecl.value) || anioDef }),
() => ({ clase: 'reporte', tipo: 'declaraciones-pdf', rfc: rfc(), year: Number(anioDecl.value) || anioDef })));

filaReporte('Dinero y saldos', 'Lo que debes y lo que te deben, con el saldo de cada factura.', null, [
['PDF', b => descargarSalida1310('salidas/pdf', { kind: 'saldos', rfc: rfc() }, b), 'primary'],
['Excel', b => descargarSalida1310('salidas/xlsx', { kind: 'dinero', rfc: rfc() }, b)],
['Imprimir', () => {
const paidBy = paidByMap();
const own = new Set(people.map(person => person.id));




const open = invoices.filter(row => row.kind === 'I' && !row.archived).map(row => {
const item = { row, ...balanceOf(row, paidBy), state: invoiceStateOf(row) };
const srv = typeof dineroServerInfo !== 'undefined' ? dineroServerInfo.get(row.id) : null;
if (srv) { item.paid = moneyCents(srv.paid || '0'); item.balance = moneyCents(srv.balance || '0'); }
return item;
})
.filter(item => item.balance > 0n && item.state !== 'Cancelado');
const filas = [];
for (const item of open.filter(i => own.has(i.row.from.rfc))) filas.push(['Por cobrar', item.row.to.name || item.row.to.rfc, dateLabel(item.row.date), '$' + centsLabel(item.balance)]);
for (const item of open.filter(i => own.has(i.row.to.rfc))) filas.push(['Por pagar', item.row.from.name || item.row.from.rfc, dateLabel(item.row.date), '$' + centsLabel(item.balance)]);




const totCobrar290 = porCobrarCanonico290();
const totPagar290 = porPagarCanonico290();
filas.push(['Por cobrar · TOTAL', totCobrar290.filas + ' factura(s) con saldo', '', '$' + centsLabel(totCobrar290.cents)]);
filas.push(['Por pagar · TOTAL', totPagar290.filas + ' factura(s) con saldo', '', '$' + centsLabel(totPagar290.cents)]);
imprimirVista201('Dinero · saldos abiertos', 'Las canceladas no entran en los saldos. Los totales son la cifra canónica del sistema: complementos de pago y marcas de pagado a mano contados, archivadas y canceladas fuera.', ['Sentido', 'Contraparte', 'Fecha', 'Saldo'], filas);
}]
], enviarReporte240('Reporte de Dinero y saldos',
() => enviarBlobSalida240('salidas/pdf', { kind: 'saldos', rfc: rfc() }),
() => ({ clase: 'reporte', tipo: 'saldos-pdf', rfc: rfc() })));






const mesConciliacion = input('month', { value: mesDef, 'aria-label': 'Mes de la conciliación' });
const bajarConciliacion230 = formato => async b => {
b.disabled = true;
try {
const mes = mesConciliacion.value || mesDef;
const blob = await satApiBlob('reportes/conciliacion?rfc=' + encodeURIComponent(rfc()) +
'&mes=' + encodeURIComponent(mes) + '&formato=' + formato);
download(blob, 'conciliacion-' + rfc() + '-' + mes + '.' + (formato === 'pdf' ? 'pdf' : 'xlsx'));
} catch (error) { toast(error.message, 'error'); }
b.disabled = false;
};
filaReporte('Conciliación de Bancos', 'La conciliación del mes en PDF para papel y en Excel para trabajarla; en Bancos se ve y se imprime en vivo.', mesConciliacion, [
['PDF', bajarConciliacion230('pdf'), 'primary'],
['Excel', bajarConciliacion230('xlsx')],
['Ver e imprimir en Bancos', () => navigate('bancos')]
], enviarReporte240(() => 'Conciliación de Bancos ' + (mesConciliacion.value || mesDef), async () => {
const mes = mesConciliacion.value || mesDef;
const blob = await satApiBlob('reportes/conciliacion?rfc=' + encodeURIComponent(rfc()) +
'&mes=' + encodeURIComponent(mes) + '&formato=pdf');
return { blob, nombre: 'conciliacion-' + rfc() + '-' + mes + '.pdf' };
}, () => ({ clase: 'reporte', tipo: 'conciliacion-pdf', rfc: rfc(), mes: mesConciliacion.value || mesDef })));

filaReporte('Avisos', 'El parte de avisos del RFC: lo que está mal, lo que falta y lo que vence.', null, [
['PDF', b => descargarSalida1310('salidas/pdf', { kind: 'avisos', rfc: scope }, b), 'primary'],
['Excel', b => descargarSalida1310('salidas/xlsx', { kind: 'avisos', rfc: scope }, b)]
], enviarReporte240('Reporte de Avisos',
() => enviarBlobSalida240('salidas/pdf', { kind: 'avisos', rfc: scope }),
() => ({ clase: 'reporte', tipo: 'avisos-pdf', rfc: scope })));
wrap.append(lista);



const cierreLink = panel('Cierre del mes y salidas por destino',
'El cierre guiado, el ZIP del mes y las salidas para tu contadora y para el banco viven en su pantalla, a un toque.');
cierreLink.append(action('Abrir Cierre y reportes', () => navigate('salidas'), 'primary', 'check'));
wrap.append(cierreLink);





const salidas280 = [wrap];
if (typeof totalsPanel === 'function') salidas280.push(totalsPanel());
if (typeof monthlyChart === 'function') salidas280.push(monthlyChart());
return salidas280;
}
const DECL_MES_REP201 = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];

function salidasScreen() {
const wrap = n('div');

const ivaPanel = panel('IVA del mes por RFC', 'IVA trasladado (lo que cobraste) e IVA acreditable (lo que te facturaron), desde el desglose guardado de cada XML. Si falta desglose, reprocésalo abajo: nunca se estima a ojo.');
const monthRow = n('div', undefined, 'filterbar');
const monthInput = input('month', { value: OUT.month, 'aria-label': 'Mes' });
monthInput.onchange = () => { OUT.month = monthInput.value || OUT.month; render(); };
monthRow.append(n('label', 'Mes '), monthInput);
ivaPanel.append(monthRow);
const rows = ivaRows(OUT.month);
if (!rows.length) ivaPanel.append(n('p', 'Sin CFDI de ingreso en ese mes para tus RFC.', 'empty'));
else ivaPanel.append(grid(['RFC', 'IVA trasladado', 'IVA acreditable', 'Saldo del mes', 'CFDI sin desglose'],
rows.map(row => [cell(row.name || row.rfc, row.rfc),
'$' + centsLabel(row.issuedIva), '$' + centsLabel(row.receivedIva),
(row.balance >= 0n ? 'A pagar ≈ $' : 'A favor ≈ $') + centsLabel(row.balance < 0n ? -row.balance : row.balance),
row.missing ? row.missing + ' (reprocesa)' : '—'])));





const faltanDesglose = rows.reduce((acc, row) => acc + (row.missing || 0), 0);
if (faltanDesglose) {
const aviso = n('div', undefined, 'cp-row');
aviso.append(n('span', number.format(faltanDesglose) + ' CFDI sin desglose de IVA: su reproceso vive en Vigilancia de CFDI.'));
const ir = n('button', 'Ir a Vigilancia de CFDI', 'soft');
ir.type = 'button';
ir.onclick = () => navigate('monitor');
aviso.append(ir);
ivaPanel.append(aviso);
}
wrap.append(ivaPanel);

const reportPanel = panel('Reporte del periodo', 'Totales del mes por sentido y por contraparte, con su IVA. Se puede imprimir, bajar en CSV o enviar por correo desde aquí.');
const cpInput = input('search', { placeholder: 'Filtrar por contraparte (nombre o RFC)…', value: OUT.cp, 'aria-label': 'Contraparte' });
cpInput.onchange = () => { OUT.cp = cpInput.value; render(); };
reportPanel.append(cpInput);
const monthInvoices = outMonthInvoices(OUT.month).filter(row =>
!OUT.cp || (row.from.name + row.from.rfc + row.to.name + row.to.rfc).toLowerCase().includes(OUT.cp.toLowerCase()));
let issuedTotal = 0n, receivedTotal = 0n, issuedIva = 0n, receivedIva = 0n;
for (const row of monthInvoices) {
if (row.currency && row.currency !== 'MXN') continue;
const role = roles(row), iva = invoiceIvaCents(row);
if (role.issued) { issuedTotal += totalCents(row); if (iva !== null) issuedIva += iva; }
if (role.received) { receivedTotal += totalCents(row); if (iva !== null) receivedIva += iva; }
}
reportPanel.append(grid(['Concepto', 'Importe'], [
['CFDI emitidos (' + monthInvoices.filter(row => roles(row).issued).length + ')', '$' + centsLabel(issuedTotal)],
['IVA trasladado del mes', '$' + centsLabel(issuedIva)],
['CFDI recibidos (' + monthInvoices.filter(row => roles(row).received).length + ')', '$' + centsLabel(receivedTotal)],
['IVA acreditable del mes', '$' + centsLabel(receivedIva)]
]));
const reportActions = n('div', undefined, 'sat-actions');
const printBtn = n('button', 'Imprimir reporte', 'soft');
printBtn.onclick = () => printPeriodReport(OUT.month, monthInvoices, { issuedTotal, receivedTotal, issuedIva, receivedIva });
const csvBtn = n('button', 'Descargar CSV del mes', 'soft');
csvBtn.onclick = () => download(new Blob(['\uFEFF', periodCsv(OUT.month)], { type: 'text/csv;charset=utf-8' }), 'reporte-' + OUT.month + '.csv');






if (typeof enviarBoton240 === 'function' && (typeof guestMode === 'undefined' || !guestMode)) {
const csvEnviar = enviarBoton240(() => ({
nombre: 'reporte-' + OUT.month + '.csv',
asunto: 'PacoSAT · Reporte ' + OUT.month,
correo: null,
correoNota: 'Este CSV se compone en tu aparato, no lo genera el servidor, y por eso no está entre los que el correo de PacoSAT puede adjuntar por la ruta de Enviar: mándalo por WhatsApp o Compartir, o usa el «Enviar por correo» de esta misma fila, que lo adjunta por el camino de siempre.',
archivo: async () => ({ blob: new Blob(['\uFEFF', periodCsv(OUT.month)], { type: 'text/csv;charset=utf-8' }),
nombre: 'reporte-' + OUT.month + '.csv' }) }));
csvEnviar.dataset.enviarCsv240 = '1';
reportActions.append(csvEnviar);
}
const mailBtn = n('button', 'Enviar por correo', 'soft');
mailBtn.onclick = () => composeMailDialog({ subject: 'PacoSAT · Reporte ' + OUT.month,
text: 'Adjunto el reporte del mes ' + OUT.month + ' generado por PacoSAT.',
attachments: [{ filename: 'reporte-' + OUT.month + '.csv', content: encode64(new TextEncoder().encode(periodCsv(OUT.month))) }] });
reportActions.append(printBtn, csvBtn, mailBtn);
reportPanel.append(reportActions);
wrap.append(reportPanel);



if (satToken) wrap.append(salidasDisenadasPanel());


if (satToken) { wrap.append(cierre200gPanel()); wrap.append(valor200gPanel()); }
else wrap.append(panel('Salidas por destino (PDF y Excel)', 'Los PDF de papel y los Excel reales los construye el servidor de PacoSAT: conecta la app en modo servidor (NAS) para descargarlos desde aquí.'));


if (satToken) wrap.append(manoFilPanel());

wrap.append(yoyPanel());




const cierrePointer = panel('Cierre del mes', 'La lista de pasos del cierre, con su estado y el camino a resolver cada uno, vive en su pestaña.');
cierrePointer.append(action('Abrir el cierre guiado', () => { cierreSection = 'cierre'; render(); }, 'primary', 'check'));
wrap.append(cierrePointer);




return [wrap];
}



async function salidaDescargar(ruta, payload, boton) {
const texto = boton ? boton.textContent : '';
if (boton) { boton.disabled = true; boton.textContent = 'Preparando…'; }
try {
const data = await satApi(ruta, payload);
download(new Blob([decode64(data.content)], { type: data.type || 'application/octet-stream' }), data.name);
toast('Salida lista: ' + data.name, 'ok');
} catch (error) { toast(error.message, 'error'); }
finally { if (boton) { boton.disabled = false; boton.textContent = texto; } }
