function frescuraEdad240(at) {
const ts = typeof at === 'number' ? at : Date.parse(at);
if (!Number.isFinite(ts)) return '';
const edad = Date.now() - ts;
if (edad < 86400000) return 'fresco';
if (edad <= 7 * 86400000) return 'viejo';
return 'caduco';
}
