wrap.dataset.edad = edad;
const track = n('span', undefined, 'frescura240-track');
track.append(n('i', undefined, 'frescura240-fill'));
wrap.append(track, n('span', haceText(typeof at === 'number' ? at : Date.parse(at)), 'frescura240-texto'));
return wrap;
}
