async function pagosMovimientoCoincidente1310(totalCents) {
try {
const data = await satApi('banks/movements');
const hoyMs = Date.now();
return (data.movements || []).find(mv => {
const cents = mv.amountCents !== undefined ? Number(mv.amountCents) : Number(moneyCents(mv.amount || '0'));
if (Math.abs(cents) !== Number(totalCents)) return false;
const fecha = Date.parse(String(mv.date || '') + 'T12:00:00');
return Number.isFinite(fecha) && Math.abs(hoyMs - fecha) <= 5 * 86400000;
}) || null;
} catch { return null; }
}
