function pagosCruce69b240(lineas, data) {
const avisos = [];
const porRfc = new Map((data?.counterparts || []).map(cp => [cp.rfc, cp]));
const eventos = data?.events || [];
for (const linea of lineas || []) {
const rfc = String(linea?.rfc || '').toUpperCase();
if (!rfc) continue;
const cp = porRfc.get(rfc);
if (!cp) continue;
const hits = (cp.hits || []).filter(hit =>
(hit.listId === '69b' || hit.listId === '69b-bis') && hit.severity !== 'ok');
if (!hits.length) continue;
let reciente = false, cuando = '';
for (const evento of eventos) {
if (evento.rfc !== rfc || (evento.listId !== '69b' && evento.listId !== '69b-bis')) continue;
const cambio = String(evento.change || '');
if (cambio.startsWith('Alta nueva')) {
reciente = true;
cuando = 'alta nueva en el listado' + (evento.at ? ' el ' + localDate(evento.at) : '');
break;
}
if (cambio.startsWith('Cambio de situación')) {
const partes = String(evento.detail || '').split('→').map(parte => parte.trim());
const nuevo = partes[partes.length - 1] || '', viejo = partes[0] || '';
if (/definitiv/i.test(nuevo) && !/definitiv/i.test(viejo)) {
reciente = true;
cuando = 'su situación empeoró a Definitivo' + (evento.at ? ' el ' + localDate(evento.at) : '');
break;
}
}
}
avisos.push({ rfc, nombre: linea.nombre || cp.name || rfc,
folio: linea.folio || '', uuid: linea.uuid || '',
lista: hits.map(hit => hit.label).join(' · '),
detalle: hits.map(hit => hit.detail).join(' · '),
definitivo: hits.some(hit => hit.severity === 'bad' || /definitiv/i.test(hit.detail || '')),
reciente, cuando });
}
return avisos;
}




