function cascadaMes240(rows, monthKey, propios) {
let cobrado = 0n, pagado = 0n;
const porId = new Map();
for (const row of rows || []) if (row?.kind === 'I' && row.id) porId.set(row.id, row);
const cancelada = row => typeof invoiceStateOf === 'function' && invoiceStateOf(row) === 'Cancelado';
for (const row of rows || []) {
if (!row) continue;
if (row.kind === 'I') {
if (row.fiscal?.paymentMethod !== 'PUE' || cancelada(row)) continue;
if (String(row.date || '').slice(0, 7) !== monthKey) continue;
if (propios.has(row.from?.rfc)) cobrado += totalCents(row);
else if (propios.has(row.to?.rfc)) pagado += totalCents(row);
} else if (row.kind === 'P') {
for (const pago of row.fiscal?.payments?.pagos || []) {
if (String(pago.fechaPago || '').slice(0, 7) !== monthKey) continue;
for (const doc of pago.documentos || []) {
const factura = porId.get(doc.idDocumento);
if (!factura || cancelada(factura) || factura.fiscal?.paymentMethod === 'PUE') continue;
const cents = moneyCents(doc.impPagado);
if (propios.has(factura.from?.rfc)) cobrado += cents;
else if (propios.has(factura.to?.rfc)) pagado += cents;
}
}
}
}
return { cobrado, pagado, saldo: cobrado - pagado };
}






